Q: How to check if a function is a constructor A: <p>If speed is what you're after and you're not worried about edge cases:</p>
<pre><code>typeof value=='function' &amp;&amp; !!value.prototype
</code></pre>
<p>But these days there are better ways, like this cross-browser solution that also works with bound functions:</p>
<pre><code>var isConstructor = typeof Proxy=='function'?
function(value) {// Tested in modern environments that support ES6 (ES2015)
    if (typeof value=='function') {
        try {// Throws if `value` is not a constructor function
            var success = new new Proxy(value, {construct:Object});
        }
        catch(e) {
        }
    }
    return !!success
}:
function(value) {// Tested in Internet Explorer 6 and up and other pre-ES6 environments
    if (Object(value)===value) {//typeof constructor=='function' isn't always true in IE
        try {
            // instanceof throws when no prototype property in function or bound target.
            // The check after `instanceof` is necessary to avoid generator functions
            // and avoid host objects in IE with this quirk: !!alert.prototype// true
            var success = {} instanceof value || !value.prototype || {}.toString.call(value)!='[object GeneratorFunction]' &amp;&amp; !/^\s*\w+ [a-z_]\w*\(\) {\s*\[native c/.test(value);
        }
        catch(e) {
        }
    }
    return !!success
}
isConstructor(window)//false
isConstructor(function myFunc(){})//true
isConstructor(function* myGenerator(){})//false
isConstructor(function myBound(){}.bind())//true
isConstructor(alert)//false
isConstructor(XMLHttpRequest)//true
// Caveat: IE returns false-positives on bound host objects
isConstructor(alert.bind())//false (true in IE)
isConstructor(setTimeout.bind())//false (true in IE)
</code></pre>
<p>Here's best of both worlds. This prioritizes speed over edge cases while still supporting bound functions in ES6+ environments.</p>
<pre><code>function isConstructorFast(value) {
    if (typeof value=='function') {
        if (value.prototype) {
            var success = true;
        }
        else if (/^bound /.test(value.name)) {
            try {
                success = new new Proxy(value, {construct:Object});
            }
            catch(e) {
            }
        }
    }
    return !!success;
}
</code></pre>
